#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b)  {
    return a < b ? a : b;
}
int mx(int a, int b)  {
    return a > b ? a : b;
}
int read(void)  {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int i = 0, l = 0, left = 0, m = 0, n = 0, r = 0, right = 0, t = 0;
    // 输入有序但可能重复；需要两个零起点下标，不是出现次数。
    n = read();
    t = read();
    for (i = 0; i < n; i += 1)  {
        a[i] = read();
    }
    left = (-1);
    right = (-1);
    l = 0;
    r = n;
    // 第一次用 <target 寻找下界，第二次用 <=target 寻找上界。
    while (l < r)  {
        m = ((l + r) / 2);
        if (a[m] < t)  {
            l = (m + 1);
        }
        else  {
            r = m;
        }
    }
    if ((l < n) && (a[l] == t))  {
        left = l;
    }
    l = 0;
    r = n;
    while (l < r)  {
        m = ((l + r) / 2);
        // 等于目标也跨过中点，才能找到第一个严格大于目标的位置。
        if (a[m] <= t)  {
            l = (m + 1);
        }
        else  {
            r = m;
        }
    }
    if (left != (-1))  {
        right = (l - 1);
    }
    // 确认目标存在后才用上界减一；不存在时两项均输出 -1。
    emit(left);
    emit(right);
    return 0;
}

